import React, { useState, useEffect } from 'react';
import { QRCodeSVG } from 'qrcode.react';
import axios from 'axios';
import { supabase } from '@/lib/supabase';
import { getUpiConfigForTransaction } from '@/config/upiConfig';
import { CheckCircle2, Loader2, AlertCircle, ShieldCheck, ArrowRight, Lock, CreditCard, Copy, Clock, ArrowLeft, Check, Download, CloudUpload, FileImage, Shield, Search } from 'lucide-react';
import { useParams, useSearchParams } from 'next/navigation';
import { generateInvoice } from '@/utils/invoiceGenerator';

interface PaymentState {
    step: 'details' | 'payment' | 'verifying' | 'success' | 'failed' | 'expired' | 'manual_upload' | 'verified' | 'review_pending';
    amount: string;
    name: string;
    email: string;
    utr: string;
    error: string;
    screenshot_url?: string;
}



export default function PaymentPageContent() {
    const params = useParams();
    const searchParams = useSearchParams();
    const urlSessionId = params?.orderId as string; // This is the UUID from URL (Session ID)

    // Get query params for auto-fill
    const queryAmount = searchParams.get('amount');
    const queryName = searchParams.get('name');
    const queryEmail = searchParams.get('email');

    const [state, setState] = useState<PaymentState>({
        step: 'details',
        amount: '',
        name: '',
        email: '',
        utr: '',
        error: '',
    });

    const [sessionId, setSessionId] = useState<string>(urlSessionId || '');
    const [officialOrderId, setOfficialOrderId] = useState<string>(''); // This will be the SF-2025-X ID
    const [copied, setCopied] = useState(false);
    const [timeLeft, setTimeLeft] = useState(15 * 60); // 15 minutes in seconds
    const [verificationStatus, setVerificationStatus] = useState('Connecting to bank...');

    // Dynamic UPI Config based on session
    const { vpa: UPI_ID, merchantName: MERCHANT_NAME } = getUpiConfigForTransaction(sessionId);
    // Effect to handle auto-fill and auto-step
    useEffect(() => {
        // 1. Priority: URL Query Params (Direct Link)
        if (queryAmount && queryName && queryEmail) {
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (emailRegex.test(queryEmail)) {
                setState(prev => ({
                    ...prev,
                    amount: queryAmount,
                    name: queryName,
                    email: queryEmail,
                    step: 'payment'
                }));
            } else {
                setState(prev => ({
                    ...prev,
                    amount: queryAmount,
                    name: queryName,
                    email: queryEmail
                }));
            }
        }
        // 2. Priority: Fetch from DB using Session ID (API Created Order)
        else if (urlSessionId) {
            const fetchOrderDetails = async () => {
                try {
                    // Try to find by ID (UUID) or session_id
                    const { data, error } = await supabase
                        .from('transactions')
                        .select('*')
                        .or(`id.eq.${urlSessionId},session_id.eq.${urlSessionId}`)
                        .single();

                    if (data) {
                        // If found, pre-fill details
                        setState(prev => ({
                            ...prev,
                            amount: data.amount.toString(),
                            name: data.customer_details?.name || '',
                            email: data.customer_details?.email || '',
                            // If status is already verified, show success
                            step: data.status === 'verified' ? 'verified' :
                                data.status === 'pending_payment' ? 'payment' : 'details'
                        }));

                        if (data.order_id) setOfficialOrderId(data.order_id);
                    }
                } catch (err) {
                    console.error("Error fetching order:", err);
                }
            };
            fetchOrderDetails();
            setSessionId(urlSessionId);
        }
    }, [queryAmount, queryName, queryEmail, urlSessionId]);

    useEffect(() => {
        let timer: ReturnType<typeof setInterval>;
        if (state.step === 'verifying') {
            const messages = [
                'Connecting to bank...',
                'Checking UTR validity...',
                'Verifying amount...',
                'Confirming with merchant...',
                'Finalizing transaction...'
            ];
            let i = 0;
            const interval = setInterval(() => {
                i = (i + 1) % messages.length;
                setVerificationStatus(messages[i]);
            }, 2000);
            return () => clearInterval(interval);
        }
    }, [state.step]);

    useEffect(() => {
        if (urlSessionId) {
            setSessionId(urlSessionId);
        }
    }, [urlSessionId]);

    useEffect(() => {
        let timer: ReturnType<typeof setInterval>;
        if (state.step === 'payment' && timeLeft > 0) {
            timer = setInterval(() => {
                setTimeLeft((prev) => prev - 1);
            }, 1000);
        } else if (timeLeft === 0 && state.step === 'payment') {
            setState(prev => ({ ...prev, step: 'expired' }));
        }
        return () => clearInterval(timer);
    }, [state.step, timeLeft]);

    const formatTime = (seconds: number) => {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins}:${secs.toString().padStart(2, '0')}`;
    };

    const handleDetailsSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!state.amount || !state.name || !state.email) {
            setState(prev => ({ ...prev, error: 'Please fill in all fields' }));
            return;
        }

        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(state.email)) {
            setState(prev => ({ ...prev, error: 'Please enter a valid email address' }));
            return;
        }

        setTimeLeft(15 * 60); // Reset timer
        setState(prev => ({ ...prev, step: 'payment', error: '' }));
    };

    const handleVerify = async () => {
        if (!state.utr || state.utr.length !== 12) {
            setState(prev => ({ ...prev, error: 'UTR number must be exactly 12 digits' }));
            return;
        }

        setState(prev => ({ ...prev, step: 'verifying', error: '' }));

        // 1. Check if UTR is already used
        try {
            const { data: existingTxn, error: checkError } = await supabase
                .from('transactions')
                .select('*')
                .eq('utr', state.utr)
                .eq('status', 'verified')
                .single();

            if (checkError && checkError.code !== 'PGRST116') { // PGRST116 is "Row not found"
                console.error('Error checking UTR:', checkError);
                setState(prev => ({ ...prev, step: 'failed', error: 'Error checking transaction status' }));
                return;
            }

            if (existingTxn) {
                setState(prev => ({ ...prev, step: 'failed', error: 'This UTR has already been used for a verified payment.' }));
                return;
            }
        } catch (err) {
            console.error('Unexpected error checking UTR:', err);
        }

        //  Check every 5 seconds for up to 2 minutes (24 attempts)
        let attempts = 0;
        const maxAttempts = 1;
        const pollInterval = 5000; // 5 seconds

        const checkPayment = async () => {
            try {
                attempts++;


                const response = await axios.post('/api/verify-payment', {
                    utr: state.utr,
                    amount: state.amount,
                    orderId: sessionId, // Pass Session ID to backend for tracking
                    email: state.email,
                    name: state.name
                });

                if (response.data.success) {
                    // Success! Record in Supabase
                    // The DB Trigger will automatically generate the 'order_id' (SF-2025-X) because status is verified

                    const { data: insertedData, error: dbError } = await supabase
                        .from('transactions')
                        .insert([
                            {
                                amount: state.amount,
                                utr: state.utr,
                                session_id: sessionId, // Store UUID in session_id
                                status: 'verified',
                                customer_details: { name: state.name, email: state.email },
                            },
                        ])
                        .select()
                        .single();

                    let finalData = insertedData;

                    if (dbError) {
                        console.error('Supabase error:', dbError);
                        // If duplicate UTR, fetch the existing one
                        if (dbError.code === '23505') {
                            const { data: existingData } = await supabase
                                .from('transactions')
                                .select()
                                .eq('utr', state.utr)
                                .single();
                            finalData = existingData;
                        }
                    }

                    if (finalData && finalData.order_id) {
                        setOfficialOrderId(finalData.order_id);
                    }

                    setState(prev => ({ ...prev, step: 'success' }));
                    return true; // Stop polling
                } else {
                    // Not found yet
                    if (attempts >= maxAttempts) {
                        // Switch to manual upload instead of failed
                        setState(prev => ({ ...prev, step: 'manual_upload', error: '' }));
                        return true; // Stop polling
                    }
                    return false; // Continue polling
                }
            } catch (err: any) {
                console.error('Verification error:', err);
                // If it's a network error, we might want to keep retrying, but for now let's fail after max attempts
                if (attempts >= maxAttempts) {
                    setState(prev => ({ ...prev, step: 'failed', error: err.response?.data?.message || 'Server error during verification' }));
                    return true;
                }
                return false;
            }
        };

        // Start polling loop
        const poll = async () => {
            const stop = await checkPayment();
            if (!stop) {
                setTimeout(poll, pollInterval);
            }
        };

        poll();
    };

    const copyToClipboard = (text: string) => {
        navigator.clipboard.writeText(text);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    // Generate UPI Intent Link
    const upiUrl = `upi://pay?pa=${UPI_ID}&pn=${encodeURIComponent(MERCHANT_NAME)}&am=${state.amount}&cu=INR`;

    const [uploading, setUploading] = useState(false);

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setUploading(true);
        try {
            // 1. Insert transaction FIRST to get the Order ID (if generated) or at least the Transaction ID
            const { data: insertedData, error: insertError } = await supabase
                .from('transactions')
                .insert({
                    utr: state.utr || `MANUAL-${Date.now()}`, // Fallback if no UTR entered
                    amount: state.amount,
                    session_id: sessionId, // Store UUID in session_id
                    status: 'pending_manual_verification',
                    customer_details: { name: state.name, email: state.email }
                    // screenshot_url is initially null
                })
                .select()
                .single();

            if (insertError) throw insertError;

            // 2. Determine filename using Order ID (preferred) or Session ID
            const fileExt = file.name.split('.').pop();
            // If order_id exists (e.g. SF-2025-1001), use it. Otherwise fallback to sessionId.
            const baseName = insertedData?.order_id || sessionId;
            const fileName = `${baseName}.${fileExt}`;
            const filePath = `${fileName}`;

            // 3. Upload the file
            const { error: uploadError } = await supabase.storage
                .from('payment_proofs')
                .upload(filePath, file, {
                    upsert: true // Overwrite if exists
                });

            if (uploadError) throw uploadError;

            const { data: { publicUrl } } = supabase.storage
                .from('payment_proofs')
                .getPublicUrl(filePath);

            // 4. Update the transaction with the screenshot URL
            const { error: updateError } = await supabase
                .from('transactions')
                .update({ screenshot_url: publicUrl })
                .eq('id', insertedData.id);

            if (updateError) throw updateError;

            // Update local state
            if (insertedData && insertedData.order_id) {
                setOfficialOrderId(insertedData.order_id);
            }

            setState(prev => ({ ...prev, step: 'success', screenshot_url: publicUrl }));
        } catch (error: any) {
            console.error('Error uploading:', error);
            if (error.code === '23505' || error.message?.includes('duplicate key')) {
                setState(prev => ({ ...prev, error: 'This UTR has already been submitted. Please check your status.' }));
            } else {
                setState(prev => ({ ...prev, error: error.message || 'Error uploading screenshot' }));
            }
        } finally {
            setUploading(false);
        }
    };

    // Listen for status updates (e.g. Admin approval)
    useEffect(() => {
        if (!sessionId) return;



        const subscription = supabase
            .channel(`transaction_${sessionId}`)
            .on(
                'postgres_changes',
                {
                    event: 'UPDATE',
                    schema: 'public',
                    table: 'transactions',
                    filter: `session_id=eq.${sessionId}` // Listen specifically for this session UUID
                },
                (payload) => {

                    const newStatus = payload.new.status;
                    const newOrderId = payload.new.order_id;

                    if (newStatus === 'verified') {
                        if (newOrderId) {
                            setOfficialOrderId(newOrderId);
                        }
                        setState(prev => ({ ...prev, step: 'verified' }));

                        // Trigger email receipt
                        axios.post('/api/send-receipt', {
                            utr: state.utr,
                            email: state.email,
                            name: state.name
                        }).catch(err => console.error('Error sending receipt:', err));

                    } else if (newStatus === 'rejected') {
                        setState(prev => ({ ...prev, step: 'failed', error: 'Payment verification rejected by admin.' }));
                    }
                }
            )
            .subscribe();

        return () => {
            supabase.removeChannel(subscription);
        };
    }, [sessionId]);

    const checkStatus = async () => {
        // If we have an official order ID, check by that.
        // If not, check by session_id or UTR.
        if (!officialOrderId && !sessionId && !state.utr) return;

        try {
            let query = supabase.from('transactions').select('status, order_id');

            if (officialOrderId) {
                query = query.eq('order_id', officialOrderId);
            } else if (sessionId) {
                query = query.eq('session_id', sessionId);
            } else {
                query = query.eq('utr', state.utr);
            }

            const { data, error } = await query.maybeSingle();

            if (error) throw error;

            if (!data) {
                alert('Transaction not found. Please ensure you have submitted the details.');
                return;
            }

            if (data.status === 'verified') {
                if (data.order_id) setOfficialOrderId(data.order_id);
                setState(prev => ({ ...prev, step: 'verified' }));
            } else if (data.status === 'rejected') {
                setState(prev => ({ ...prev, step: 'failed', error: 'Payment verification rejected by admin.' }));
            } else if (data.status === 'pending_manual_verification') {
                setState(prev => ({ ...prev, step: 'review_pending' }));
            } else {
                alert('Payment status: ' + (data.status || 'pending'));
            }
        } catch (err: any) {
            console.error('Error checking status:', err);
            alert('Error checking status: ' + (err.message || 'Unknown error'));
        }
    };

    const [loading, setLoading] = useState(true);
    const [loadingStep, setLoadingStep] = useState(0);

    useEffect(() => {
        // Step 0: Initial (0ms)
        // Step 1: Securing (500ms)
        // Step 2: Verifying (1200ms)
        // Step 3: Finalizing (2000ms)
        // Finish: (2500ms)

        const timers = [
            setTimeout(() => setLoadingStep(1), 500),
            setTimeout(() => setLoadingStep(2), 1200),
            setTimeout(() => setLoadingStep(3), 2000),
            setTimeout(() => setLoading(false), 2500),
        ];

        return () => timers.forEach(clearTimeout);
    }, []);

    if (loading) {
        const steps = [
            "Initializing secure environment...",
            "Encrypting connection...",
            "Verifying merchant details...",
            "Preparing payment gateway..."
        ];

        const icons = [
            <Shield size={24} className="text-[#635BFF]" />,
            <Lock size={24} className="text-[#635BFF]" />,
            <Search size={24} className="text-[#635BFF]" />,
            <CreditCard size={24} className="text-[#635BFF]" />
        ];

        return (
            <div className="min-h-screen bg-white flex flex-col items-center justify-center p-4 relative overflow-hidden font-sans">
                {/* Tech Background Grid */}
                <div className="absolute inset-0 bg-[linear-gradient(to_right,#80808012_1px,transparent_1px),linear-gradient(to_bottom,#80808012_1px,transparent_1px)] bg-[size:24px_24px]"></div>
                <div className="absolute inset-0 bg-[radial-gradient(circle_800px_at_100%_200px,#C9EBFF,transparent)]"></div>

                <div className="relative z-10 flex flex-col items-center w-full max-w-sm">
                    {/* Logo */}
                    <div className="mb-8 animate-fade-in relative group">
                        <div className="absolute inset-0 bg-blue-500/20 blur-xl rounded-full opacity-0 group-hover:opacity-30 transition-opacity duration-700"></div>
                        <img
                            src="/shark-logo-full.png"
                            alt="Shark Funded"
                            className="h-14 object-contain animate-float relative z-10"
                        />
                        {/* Shimmer Overlay */}
                        <div className="absolute inset-0 z-20 pointer-events-none overflow-hidden rounded-lg">
                            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/40 to-transparent -translate-x-full animate-logo-shimmer"></div>
                        </div>
                    </div>

                    {/* Dynamic Icon Container */}
                    <div className="mb-8 w-16 h-16 bg-white rounded-2xl shadow-lg shadow-indigo-100 border border-indigo-50 flex items-center justify-center relative overflow-hidden">
                        {icons.map((icon, index) => (
                            <div
                                key={index}
                                className={`absolute transition-all duration-500 transform ${index === loadingStep
                                    ? 'opacity-100 scale-100 rotate-0'
                                    : 'opacity-0 scale-50 rotate-12'
                                    }`}
                            >
                                {icon}
                            </div>
                        ))}
                    </div>

                    {/* Progress Bar */}
                    <div className="w-full h-1 bg-slate-100 rounded-full overflow-hidden mb-6 relative">
                        <div
                            className="absolute top-0 left-0 h-full bg-[#635BFF] transition-all duration-700 ease-out rounded-full"
                            style={{ width: `${((loadingStep + 1) / 4) * 100}%` }}
                        ></div>
                        {/* Shimmer Effect on Bar */}
                        <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-r from-transparent via-white/30 to-transparent animate-shimmer" style={{ backgroundSize: '200% 100%' }}></div>
                    </div>

                    {/* Status Text */}
                    <div className="h-6 flex items-center justify-center overflow-hidden relative w-full">
                        {steps.map((text, index) => (
                            <p
                                key={index}
                                className={`absolute text-sm font-medium text-slate-600 transition-all duration-500 transform ${index === loadingStep
                                    ? 'opacity-100 translate-y-0'
                                    : index < loadingStep
                                        ? 'opacity-0 -translate-y-4'
                                        : 'opacity-0 translate-y-4'
                                    }`}
                            >
                                {text}
                            </p>
                        ))}
                    </div>

                    {/* Security Badge (Appears at Step 2) */}
                    <div className={`mt-12 transition-all duration-700 ${loadingStep >= 2 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
                        <div className="flex items-center gap-2 px-4 py-2 bg-white/50 backdrop-blur-sm rounded-full border border-slate-200 shadow-sm">
                            <ShieldCheck size={14} className="text-emerald-500" />
                            <span className="text-xs font-semibold text-slate-600">Bank-Grade Security</span>
                        </div>
                    </div>
                </div>

                <style jsx>{`
                    @keyframes float {
                        0%, 100% { transform: translateY(0px); }
                        50% { transform: translateY(-8px); }
                    }
                    @keyframes logo-shimmer {
                        0% { transform: translateX(-150%) skewX(-15deg); }
                        100% { transform: translateX(150%) skewX(-15deg); }
                    }
                    @keyframes shimmer {
                        0% { transform: translateX(-100%); }
                        100% { transform: translateX(100%); }
                    }
                    @keyframes breath {
                        0%, 100% { transform: scale(1); filter: drop-shadow(0 0 0px rgba(99, 91, 255, 0)); }
                        50% { transform: scale(1.05); filter: drop-shadow(0 0 10px rgba(99, 91, 255, 0.2)); }
                    }
                    .animate-float {
                        animation: float 4s ease-in-out infinite;
                    }
                    .animate-logo-shimmer {
                        animation: logo-shimmer 2.5s infinite;
                    }
                    .animate-shimmer {
                        animation: shimmer 1.5s infinite;
                    }
                    .animate-breath {
                        animation: breath 3s ease-in-out infinite;
                    }
                `}</style>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-[#F0F2F5] flex items-center justify-center p-4 font-sans selection:bg-slate-900 selection:text-white">

            <div className="bg-white w-full max-w-5xl rounded-2xl shadow-2xl overflow-hidden flex flex-col md:flex-row min-h-[600px] animate-slide-up">

                {/* Left Sidebar (Razorpay Style) */}
                <div className="md:w-[350px] bg-[#F9FAFB] border-r border-slate-100 p-8 flex flex-col justify-between relative">
                    <div>
                        <div className="flex flex-col items-start gap-4 mb-8">
                            <div className="w-48 h-auto">
                                <img src="/shark-logo-full.png" alt="Shark Funded" className="w-full h-full object-contain" />
                            </div>
                            <div className="flex items-center gap-1.5 text-xs font-medium text-slate-600 bg-white px-3 py-1 rounded-full border border-slate-200 shadow-sm">
                                <ShieldCheck size={12} className="text-emerald-500" />
                                <span>Trusted Merchant</span>
                            </div>
                        </div>

                        <div className="space-y-6">
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Amount to Pay</p>
                                <div className="flex items-baseline gap-1">
                                    <span className="text-3xl font-bold text-slate-900">₹{state.amount ? Number(state.amount).toLocaleString() : '0.00'}</span>
                                    <span className="text-slate-500 text-sm font-medium">INR</span>
                                </div>
                            </div>

                            {/* Official Order ID (Only on Success) */}
                            {officialOrderId && (
                                <div className="bg-emerald-50 p-3 rounded-lg border border-emerald-100 shadow-sm animate-fade-in">
                                    <p className="text-xs text-emerald-600 mb-1 font-bold">Order ID</p>
                                    <p className="font-mono text-sm font-bold text-emerald-800 break-all">{officialOrderId}</p>
                                </div>
                            )}

                            <div className="space-y-3 pt-6 border-t border-slate-200">
                                <div className="flex items-center gap-3">
                                    <div className="w-8 h-8 rounded-full bg-blue-50 flex items-center justify-center text-blue-600">
                                        <Lock size={14} />
                                    </div>
                                    <div>
                                        <p className="text-xs font-bold text-slate-700">Secure Payment</p>
                                        <p className="text-[10px] text-slate-500">256-bit SSL Encrypted</p>
                                    </div>
                                </div>
                                <div className="flex items-center gap-3">
                                    <div className="w-8 h-8 rounded-full bg-emerald-50 flex items-center justify-center text-emerald-600">
                                        <Check size={14} />
                                    </div>
                                    <div>
                                        <p className="text-xs font-bold text-slate-700">Instant Verification</p>
                                        <p className="text-[10px] text-slate-500">Automated confirmation</p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="mt-8 md:mt-0 pt-6 border-t border-slate-200 md:border-0 md:pt-0">
                        <div className="flex items-center gap-2 opacity-60">
                            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Powered by</span>
                            <span className="text-xs font-bold text-slate-600">Shark Payments</span>
                        </div>
                    </div>
                </div>

                {/* Right Content (Stripe Style) */}
                <div className="flex-1 p-8 md:p-12 flex flex-col justify-center relative">

                    {/* Back Button */}
                    {state.step === 'payment' && (
                        <button
                            onClick={() => setState(prev => ({ ...prev, step: 'details' }))}
                            className="absolute top-8 left-8 text-slate-400 hover:text-slate-700 transition-colors flex items-center gap-1 text-sm font-medium"
                        >
                            <ArrowLeft size={16} /> Back
                        </button>
                    )}

                    <div className="max-w-md mx-auto w-full">

                        {state.step === 'details' && (
                            <form onSubmit={handleDetailsSubmit} className="space-y-6 animate-fade-in" noValidate>
                                <div className="mb-8">
                                    <h2 className="text-xl font-bold text-slate-900 mb-2">Contact Information</h2>
                                    <p className="text-slate-500 text-sm">Enter your details to proceed with the payment.</p>
                                </div>

                                <div className="space-y-5">
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Email Address</label>
                                        <input
                                            type="email"
                                            className="w-full px-4 py-3 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all outline-none text-slate-900 placeholder:text-slate-400 shadow-sm"
                                            value={state.email}
                                            onChange={e => setState({ ...state, email: e.target.value })}
                                            placeholder="sharkfunded@example.com"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Full Name</label>
                                        <input
                                            type="text"
                                            className="w-full px-4 py-3 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all outline-none text-slate-900 placeholder:text-slate-400 shadow-sm"
                                            value={state.name}
                                            onChange={e => setState({ ...state, name: e.target.value })}
                                            placeholder="Shark Funded"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Amount</label>
                                        <div className="relative">
                                            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 font-medium">₹</span>
                                            <input
                                                type="number"
                                                min="1"
                                                className="w-full pl-8 pr-4 py-3 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all outline-none text-slate-900 font-medium placeholder:text-slate-400 shadow-sm"
                                                value={state.amount}
                                                onChange={e => setState({ ...state, amount: e.target.value })}
                                                placeholder="0.00"
                                            />
                                        </div>
                                    </div>
                                </div>

                                {state.error && (
                                    <div className="p-3 bg-rose-50 text-rose-600 text-sm rounded-lg flex items-center gap-2 border border-rose-100 animate-shake">
                                        <AlertCircle size={16} />
                                        <span className="font-medium">{state.error}</span>
                                    </div>
                                )}

                                <button
                                    type="submit"
                                    className="w-full bg-[#635BFF] text-white py-3.5 rounded-lg font-bold text-sm hover:bg-[#5851E3] hover:shadow-lg hover:shadow-blue-500/20 transition-all duration-200 flex items-center justify-center gap-2 mt-4"
                                >
                                    Pay ₹{state.amount ? Number(state.amount).toLocaleString() : '0.00'}
                                    <ArrowRight size={16} />
                                </button>

                                <div className="mt-6 flex items-center justify-center gap-2 text-slate-400">
                                    <Lock size={12} />
                                    <span className="text-[10px] font-medium uppercase tracking-wider">256-bit SSL Encrypted</span>
                                </div>
                            </form>
                        )}

                        {state.step === 'payment' && (
                            <div className="space-y-8 animate-fade-in">
                                <div className="text-center">
                                    <h2 className="text-xl font-bold text-slate-900 mb-2">Scan QR to Pay</h2>
                                    <div className="inline-flex items-center gap-1.5 px-3 py-1 bg-amber-50 text-amber-700 rounded-full text-xs font-bold border border-amber-100">
                                        <Clock size={12} className="animate-pulse" />
                                        Expires in {formatTime(timeLeft)}
                                    </div>
                                </div>

                                <div className="flex flex-col items-center">
                                    <div className="mb-4 text-center">
                                        <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Paying to</p>
                                        <p className="text-lg font-bold text-slate-900">{MERCHANT_NAME}</p>
                                    </div>

                                    <div className="p-1 bg-white rounded-xl border border-slate-200 shadow-sm mb-4 cursor-pointer hover:shadow-md transition-all" onClick={() => copyToClipboard(upiUrl)}>
                                        <QRCodeSVG value={upiUrl} size={180} level="L" className="rounded-lg" />
                                        {copied && (
                                            <div className="absolute inset-0 flex items-center justify-center bg-white/90 rounded-xl backdrop-blur-sm">
                                                <span className="text-xs font-bold text-slate-900 flex items-center gap-1"><CheckCircle2 size={14} className="text-emerald-500" /> Copied</span>
                                            </div>
                                        )}
                                    </div>

                                    <div className="flex items-center gap-2 text-sm text-slate-600 bg-slate-50 px-3 py-1.5 rounded-md border border-slate-200 cursor-pointer hover:bg-slate-100" onClick={() => copyToClipboard(UPI_ID)}>
                                        <span className="font-mono font-medium">{UPI_ID}</span>
                                        <Copy size={14} className="text-slate-400" />
                                    </div>

                                    <div className="mt-6 flex flex-col items-center gap-3">
                                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Accepted Payment Apps</p>
                                        <div className="flex items-center gap-6">
                                            <img src="https://static.cdnlogo.com/logos/p/6/paytm.svg" alt="Paytm" className="h-6 object-contain" />
                                            <img src="https://static.cdnlogo.com/logos/p/25/phonepe.svg" alt="PhonePe" className="h-20 object-contain" />
                                            <img src="https://static.cdnlogo.com/logos/g/80/google-pay.png" alt="Google Pay" className="h-20 object-contain" />

                                        </div>
                                    </div>
                                </div>

                                <div className="pt-6 border-t border-slate-100">
                                    <label className="block text-sm font-medium text-slate-700 mb-2">Enter UTR / Reference Number</label>
                                    <div className="flex gap-2">
                                        <input
                                            type="text"
                                            className="flex-1 px-4 py-3 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all outline-none text-slate-900 font-mono font-medium placeholder:text-slate-400 shadow-sm"
                                            placeholder="12-digit UTR"
                                            value={state.utr}
                                            onChange={e => setState({ ...state, utr: e.target.value })}
                                        />
                                        <button
                                            onClick={handleVerify}
                                            className="px-6 bg-[#635BFF] text-white rounded-lg font-bold text-sm hover:bg-[#5851E3] transition-all shadow-md hover:shadow-lg hover:shadow-blue-500/20"
                                        >
                                            Verify
                                        </button>
                                    </div>
                                    <p className="text-xs text-slate-400 mt-2">
                                        Required to confirm your payment instantly.
                                    </p>
                                    {state.error && (
                                        <div className="mt-3 p-3 bg-rose-50 text-rose-600 text-sm rounded-lg flex items-center gap-2 border border-rose-100 animate-shake">
                                            <AlertCircle size={16} />
                                            <span className="font-medium">{state.error}</span>
                                        </div>
                                    )}
                                </div>

                                <div className="mt-8 flex items-center justify-center gap-2 text-slate-400">
                                    <Lock size={12} />
                                    <span className="text-[10px] font-medium uppercase tracking-wider">256-bit SSL Encrypted</span>
                                </div>
                            </div>
                        )}

                        {state.step === 'verifying' && (
                            <div className="text-center py-12 space-y-8 animate-fade-in relative overflow-hidden">
                                {/* Background Pulse Effect */}
                                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 bg-indigo-50 rounded-full animate-ping opacity-20"></div>
                                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-48 h-48 bg-indigo-100 rounded-full animate-ping opacity-30 delay-75"></div>

                                <div className="relative z-10">
                                    <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center mx-auto shadow-xl border-4 border-indigo-50 relative">
                                        <div className="absolute inset-0 border-4 border-[#635BFF] border-t-transparent rounded-full animate-spin"></div>
                                        <ShieldCheck size={32} className="text-[#635BFF] animate-pulse" />
                                    </div>
                                </div>

                                <div className="space-y-2 relative z-10">
                                    <h3 className="text-xl font-bold text-slate-900">Verifying Payment</h3>
                                    <div className="h-6 overflow-hidden relative">
                                        <p className="text-slate-500 text-sm font-medium animate-slide-up-fade">
                                            {verificationStatus}
                                        </p>
                                    </div>
                                </div>

                                <div className="max-w-xs mx-auto bg-slate-50 rounded-lg p-3 border border-slate-100">
                                    <div className="flex items-center gap-3">
                                        <div className="w-8 h-8 rounded-full bg-white flex items-center justify-center border border-slate-200 shadow-sm">
                                            <span className="font-mono text-xs font-bold text-slate-700">UTR</span>
                                        </div>
                                        <div className="flex-1 text-left">
                                            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Reference ID</p>
                                            <p className="text-sm font-mono font-bold text-slate-900">{state.utr}</p>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}

                        {(state.step === 'success' || state.step === 'verified') && (
                            <div className="text-center py-8 space-y-6 animate-scale-in">
                                <div className={`w-16 h-16 ${state.step === 'verified' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-[#635BFF]'} rounded-full flex items-center justify-center mx-auto`}>
                                    {state.step === 'verified' ? <CheckCircle2 size={32} /> : <Clock size={32} />}
                                </div>
                                <div>
                                    <h2 className="text-2xl font-bold text-slate-900">
                                        {state.step === 'verified' ? 'Payment Verified' : state.screenshot_url ? 'Submitted for Review' : 'Payment Successful'}
                                    </h2>
                                    <p className="text-slate-500 text-sm mt-1">
                                        {state.step === 'verified' ? 'Your transaction has been confirmed.' : state.screenshot_url ? 'We will notify you once approved.' : 'Thank you for your payment.'}
                                    </p>
                                </div>

                                <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 text-left space-y-2 text-sm">
                                    <div className="flex justify-between">
                                        <span className="text-slate-500">Amount Paid</span>
                                        <span className="font-bold text-slate-900">₹{Number(state.amount).toLocaleString()}</span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span className="text-slate-500">Order ID</span>
                                        <span className="font-mono font-bold text-slate-900 break-all">{officialOrderId || 'Generating...'}</span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span className="text-slate-500">Reference/UTR</span>
                                        <span className="font-mono font-bold text-slate-900">{state.utr}</span>
                                    </div>
                                </div>

                                <div className="space-y-3 pt-4">
                                    {state.screenshot_url && state.step !== 'verified' && (
                                        <button
                                            onClick={checkStatus}
                                            className="w-full bg-white text-slate-700 border border-slate-200 py-3 rounded-lg font-bold text-sm hover:bg-slate-50 transition-all"
                                        >
                                            Check Status
                                        </button>
                                    )}
                                    <button
                                        onClick={() => generateInvoice({
                                            orderId: officialOrderId || 'PENDING',
                                            date: new Date().toLocaleDateString(),
                                            amount: state.amount,
                                            name: state.name,
                                            email: state.email,
                                            utr: state.utr
                                        })}
                                        className="w-full bg-white text-slate-700 border border-slate-200 py-3 rounded-lg font-bold text-sm hover:bg-slate-50 transition-all flex items-center justify-center gap-2"
                                    >
                                        <Download size={16} />
                                        Download Invoice
                                    </button>
                                    <button
                                        onClick={() => window.location.reload()}
                                        className="w-full bg-[#635BFF] text-white py-3 rounded-lg font-bold text-sm hover:bg-[#5851E3] transition-all hover:shadow-lg hover:shadow-blue-500/20"
                                    >
                                        Done
                                    </button>
                                </div>
                            </div>
                        )}

                        {state.step === 'failed' && (
                            <div className="text-center py-12 space-y-8 animate-scale-in relative overflow-hidden">
                                {/* Background Pulse Effect */}
                                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 bg-rose-50 rounded-full animate-ping opacity-20"></div>

                                <div className="relative z-10">
                                    <div className="w-24 h-24 bg-rose-50 rounded-full flex items-center justify-center mx-auto shadow-sm border border-rose-100 mb-6">
                                        <div className="w-16 h-16 bg-rose-100 text-rose-600 rounded-full flex items-center justify-center shadow-inner">
                                            <AlertCircle size={32} />
                                        </div>
                                    </div>

                                    <div className="space-y-3">
                                        <h2 className="text-2xl font-bold text-slate-900">
                                            {state.error.includes('rejected') ? 'Verification Rejected' : 'Payment Failed'}
                                        </h2>
                                        <p className="text-slate-500 text-sm max-w-xs mx-auto leading-relaxed">
                                            {state.error || 'We could not verify your payment. Please check your details and try again.'}
                                        </p>
                                    </div>
                                </div>

                                <div className="space-y-3 max-w-xs mx-auto relative z-10">
                                    <button
                                        onClick={() => setState(prev => ({ ...prev, step: 'payment', error: '' }))}
                                        className="w-full bg-[#635BFF] text-white py-3.5 rounded-xl font-bold text-sm hover:bg-[#5851E3] transition-all hover:shadow-lg hover:shadow-blue-500/20 flex items-center justify-center gap-2"
                                    >
                                        <ArrowLeft size={16} />
                                        Try Again
                                    </button>

                                    <button
                                        onClick={() => window.open('mailto:support@sharkfunded.com', '_blank')}
                                        className="w-full bg-white text-slate-600 border border-slate-200 py-3.5 rounded-xl font-bold text-sm hover:bg-slate-50 hover:text-slate-900 transition-all"
                                    >
                                        Contact Support
                                    </button>
                                </div>
                            </div>
                        )}

                        {state.step === 'manual_upload' && (
                            <div className="text-center py-8 space-y-6 animate-fade-in">
                                <div className="w-16 h-16 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center mx-auto shadow-sm">
                                    <AlertCircle size={32} />
                                </div>
                                <div>
                                    <h2 className="text-xl font-bold text-slate-900">Manual Verification</h2>
                                    <p className="text-slate-500 text-sm mt-1 max-w-xs mx-auto">
                                        We couldn't verify automatically. Please upload a screenshot of your payment.
                                    </p>
                                </div>

                                <div className="relative group max-w-sm mx-auto">
                                    <input
                                        type="file"
                                        accept="image/*"
                                        onChange={handleFileUpload}
                                        className="hidden"
                                        id="file-upload"
                                        disabled={uploading}
                                    />
                                    <label
                                        htmlFor="file-upload"
                                        className={`w-full flex flex-col items-center justify-center gap-4 px-6 py-12 border-2 border-dashed border-slate-300 rounded-2xl cursor-pointer transition-all duration-300 group relative overflow-hidden ${uploading ? 'opacity-50 cursor-not-allowed' : 'hover:border-blue-500 hover:bg-blue-50/30 hover:shadow-xl hover:shadow-blue-500/10'}`}
                                    >
                                        {/* Background Pattern */}
                                        <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none"
                                            style={{ backgroundImage: 'radial-gradient(#3b82f6 1px, transparent 1px)', backgroundSize: '20px 20px' }}>
                                        </div>

                                        {uploading ? (
                                            <div className="flex flex-col items-center gap-3 relative z-10">
                                                <div className="relative">
                                                    <div className="w-16 h-16 border-4 border-slate-200 border-t-blue-600 rounded-full animate-spin"></div>
                                                    <div className="absolute inset-0 flex items-center justify-center">
                                                        <span className="text-xs font-bold text-blue-600">...</span>
                                                    </div>
                                                </div>
                                                <span className="font-bold text-sm text-slate-700 animate-pulse">Uploading Proof...</span>
                                            </div>
                                        ) : (
                                            <>
                                                <div className="w-20 h-20 bg-white text-blue-600 rounded-full flex items-center justify-center group-hover:scale-110 group-hover:-translate-y-2 transition-all duration-300 shadow-md border border-blue-100 relative z-10">
                                                    <CloudUpload size={36} className="group-hover:text-blue-500" />
                                                </div>
                                                <div className="space-y-2 relative z-10">
                                                    <p className="text-base font-bold text-slate-900 group-hover:text-blue-700 transition-colors">
                                                        Click to upload or drag and drop
                                                    </p>
                                                    <p className="text-xs text-slate-500 font-medium">
                                                        SVG, PNG, JPG or GIF (max. 5MB)
                                                    </p>
                                                </div>
                                                <div className="flex items-center gap-2 text-xs font-bold text-slate-500 bg-white px-4 py-2 rounded-full border border-slate-200 shadow-sm group-hover:border-blue-200 group-hover:text-blue-600 transition-all relative z-10">
                                                    <FileImage size={14} />
                                                    <span>Payment Screenshot</span>
                                                </div>
                                            </>
                                        )}
                                    </label>
                                </div>
                                {state.error && (
                                    <div className="p-3 bg-rose-50 text-rose-600 text-sm rounded-lg flex items-center justify-center gap-2 border border-rose-100 animate-shake">
                                        <AlertCircle size={16} />
                                        <span className="font-medium">{state.error}</span>
                                    </div>
                                )}
                            </div>
                        )}

                        {state.step === 'review_pending' && (
                            <div className="text-center py-12 space-y-6 animate-fade-in">
                                <div className="w-20 h-20 bg-amber-50 text-amber-600 rounded-full flex items-center justify-center mx-auto shadow-sm border border-amber-100">
                                    <Clock size={40} className="animate-pulse" />
                                </div>
                                <div className="space-y-2">
                                    <h2 className="text-xl font-bold text-slate-900">Payment Under Review</h2>
                                    <p className="text-slate-500 text-sm max-w-xs mx-auto leading-relaxed">
                                        Your payment is currently being reviewed by our team. We will notify you once it's approved.
                                    </p>
                                </div>
                                <div className="p-4 bg-slate-50 rounded-xl border border-slate-100 max-w-xs mx-auto">
                                    <div className="flex items-center gap-3 mb-2">
                                        <div className="w-8 h-8 rounded-full bg-white flex items-center justify-center border border-slate-200 shadow-sm">
                                            <span className="font-mono text-xs font-bold text-slate-700">ID</span>
                                        </div>
                                        <div className="flex-1 text-left">
                                            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Order ID</p>
                                            <p className="text-sm font-mono font-bold text-slate-900">{officialOrderId || 'Pending...'}</p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-2 text-xs text-slate-400 justify-center mt-3 pt-3 border-t border-slate-200">
                                        <Loader2 size={12} className="animate-spin" />
                                        <span>Checking status automatically...</span>
                                    </div>
                                </div>
                            </div>
                        )}

                        {state.step === 'expired' && (
                            <div className="text-center py-12 space-y-6 animate-scale-in">
                                <div className="w-16 h-16 bg-slate-100 text-slate-500 rounded-full flex items-center justify-center mx-auto">
                                    <Clock size={32} />
                                </div>
                                <div>
                                    <h2 className="text-xl font-bold text-slate-900">Session Expired</h2>
                                    <p className="text-slate-500 text-sm mt-1">Please start over.</p>
                                </div>
                                <button
                                    onClick={() => setState(prev => ({ ...prev, step: 'details', error: '' }))}
                                    className="w-full bg-[#635BFF] text-white py-3 rounded-lg font-bold text-sm hover:bg-[#5851E3] transition-all hover:shadow-lg hover:shadow-blue-500/20"
                                >
                                    Start Over
                                </button>
                            </div>
                        )}

                    </div>
                </div>
            </div>
        </div>
    );
};